def apply_environment_settings(qlabs):
    settings = TRACK_DATA.get('environment', {}) or {}
    if not bool(settings.get('enabled', True)):
        return
    env = QLabsEnvironmentOutdoors(qlabs)
    weather_name = str(settings.get('weather', 'clear_skies'))
    weather_map = {'clear_skies': env.CLEAR_SKIES, 'partly_cloudy': env.PARTLY_CLOUDY, 'cloudy': env.CLOUDY, 'overcast': env.OVERCAST, 'foggy': env.FOGGY, 'light_rain': env.LIGHT_RAIN, 'rain': env.RAIN, 'thunderstorm': env.THUNDERSTORM, 'light_snow': env.LIGHT_SNOW, 'snow': env.SNOW, 'blizzard': env.BLIZZARD}
    env.set_weather_preset(weather_map.get(weather_name, env.CLEAR_SKIES))
    env.set_time_of_day(max(0.0, min(24.0, float(settings.get('time_of_day', 12.0)))))

def clamp(value, low, high):
    return max(low, min(high, value))

def project_scale():
    return float(TRACK_DATA.get('project', {}).get('scale_factor', 1.0))

def rotate_local_world(local_x, local_y, editor_rotation_deg):
    angle = math.radians(-float(editor_rotation_deg))
    c = math.cos(angle)
    s = math.sin(angle)
    return (local_x * c - local_y * s, local_x * s + local_y * c)

def local_to_world_design(obj, local_x, local_y):
    rx, ry = rotate_local_world(local_x, local_y, obj.get('rotation_deg', 0.0))
    return (float(obj.get('x', 0.0)) + rx, float(obj.get('y', 0.0)) + ry)

def scaled_world_point(obj, local_x, local_y):
    scale = project_scale()
    x, y = local_to_world_design(obj, local_x, local_y)
    return (x * scale, y * scale)

def editor_yaw_to_qlabs_radians(editor_rotation_deg):
    return math.radians(-float(editor_rotation_deg))

def spawn_straight_spline(qlabs, p1, p2, width, color, z=ROAD_Z):
    spline = QLabsSplineLine(qlabs)
    spline.spawn(location=[0, 0, 0], scale=[1, 1, 1], configuration=QLabsSplineLine.LINEAR)
    spline.set_points(color=color, pointList=[[p1[0], p1[1], z, width], [p2[0], p2[1], z, width]], alignEndPointTangents=False)

def spawn_polyline_spline(qlabs, points, width, color, z=ROAD_Z):
    """Spawn one linear QLabs spline actor for a connected point sequence."""
    if len(points) < 2:
        return
    spline = QLabsSplineLine(qlabs)
    spline.spawn(location=[0, 0, 0], scale=[1, 1, 1], configuration=QLabsSplineLine.LINEAR)
    spline.set_points(color=color, pointList=[[point[0], point[1], z, width] for point in points], alignEndPointTangents=False)

def polyline_offset_design(points, offset):
    """Offset an open or closed local-world polyline with bounded miters."""
    if len(points) < 2 or abs(offset) <= 1e-09:
        return list(points)
    closed = len(points) >= 4 and math.hypot(float(points[0][0]) - float(points[-1][0]), float(points[0][1]) - float(points[-1][1])) <= 1e-09
    vertices = points[:-1] if closed else points
    normals = []
    segment_count = len(vertices) if closed else len(vertices) - 1
    for index in range(segment_count):
        start = vertices[index]
        end = vertices[(index + 1) % len(vertices)]
        dx = float(end[0]) - float(start[0])
        dy = float(end[1]) - float(start[1])
        length = math.hypot(dx, dy)
        normals.append((0.0, 0.0) if length <= 1e-09 else (-dy / length, dx / length))
    result = []
    for index, point in enumerate(vertices):
        px, py = (float(point[0]), float(point[1]))
        if not closed and index == 0:
            nx, ny = normals[0]
            result.append((px + nx * offset, py + ny * offset))
            continue
        if not closed and index == len(vertices) - 1:
            nx, ny = normals[-1]
            result.append((px + nx * offset, py + ny * offset))
            continue
        previous = normals[(index - 1) % len(normals)]
        following = normals[index]
        bx = previous[0] + following[0]
        by = previous[1] + following[1]
        magnitude = math.hypot(bx, by)
        if magnitude <= 1e-06:
            result.append((px + following[0] * offset, py + following[1] * offset))
            continue
        bx /= magnitude
        by /= magnitude
        denominator = bx * following[0] + by * following[1]
        distance = offset if abs(denominator) <= 0.2 else offset / denominator
        maximum = max(abs(offset), abs(offset) * 4.0)
        distance = clamp(distance, -maximum, maximum)
        result.append((px + bx * distance, py + by * distance))
    if closed and result:
        result.append(result[0])
    return result

def smooth_polyline_design(points, samples_per_segment=8):
    """Sample an open Catmull-Rom curve through continuous-road nodes."""
    if len(points) < 3:
        return list(points)
    result = []
    samples = max(3, int(samples_per_segment))
    for index in range(len(points) - 1):
        p0 = points[max(0, index - 1)]
        p1 = points[index]
        p2 = points[index + 1]
        p3 = points[min(len(points) - 1, index + 2)]
        for step in range(samples):
            t = step / samples
            t2 = t * t
            t3 = t2 * t
            x = 0.5 * (2.0 * p1[0] + (-p0[0] + p2[0]) * t + (2.0 * p0[0] - 5.0 * p1[0] + 4.0 * p2[0] - p3[0]) * t2 + (-p0[0] + 3.0 * p1[0] - 3.0 * p2[0] + p3[0]) * t3)
            y = 0.5 * (2.0 * p1[1] + (-p0[1] + p2[1]) * t + (2.0 * p0[1] - 5.0 * p1[1] + 4.0 * p2[1] - p3[1]) * t2 + (-p0[1] + 3.0 * p1[1] - 3.0 * p2[1] + p3[1]) * t3)
            result.append((x, y))
    result.append((float(points[-1][0]), float(points[-1][1])))
    return result

def continuous_local_points(obj):
    points = [(float(point[0]), float(point[1])) for point in obj.get('points_m', []) or [] if isinstance(point, (list, tuple)) and len(point) >= 2]
    return smooth_polyline_design(points) if bool(obj.get('smooth', False)) else points

def scaled_polyline_points(obj, points):
    return [scaled_world_point(obj, float(point[0]), float(point[1])) for point in points if isinstance(point, (list, tuple)) and len(point) >= 2]

def spawn_arc_spline(qlabs, center, yaw_rad, radius, start_angle_deg, end_angle_deg, width, color, z=ROAD_Z):
    spline = QLabsSplineLine(qlabs)
    spline.spawn(location=[center[0], center[1], z], rotation=[0, 0, yaw_rad], scale=[1, 1, 1], configuration=QLabsSplineLine.CURVE)
    sweep = abs(end_angle_deg - start_angle_deg)
    num_points = max(4, int(math.ceil(sweep / 12.0)) + 1)
    spline.arc_from_center_degrees(radius=radius, startAngle=start_angle_deg, endAngle=end_angle_deg, lineWidth=width, color=color, numSplinePoints=num_points)

def spawn_dashed_polyline(qlabs, points, width, color, z=GUIDE_Z, dash_design_m=DASH_LENGTH_DESIGN_M, gap_design_m=DASH_GAP_DESIGN_M):
    """Draw a continuous dash pattern across polyline corners."""
    if len(points) < 2:
        return
    scale = project_scale()
    dash = max(0.003, float(dash_design_m) * scale)
    gap = max(0.002, float(gap_design_m) * scale)
    drawing = True
    remaining_pattern = dash
    current_dash = []
    for segment_start, segment_end in zip(points, points[1:]):
        x = float(segment_start[0])
        y = float(segment_start[1])
        dx = float(segment_end[0]) - x
        dy = float(segment_end[1]) - y
        segment_length = math.hypot(dx, dy)
        if segment_length <= 1e-09:
            continue
        ux = dx / segment_length
        uy = dy / segment_length
        remaining_segment = segment_length
        while remaining_segment > 1e-09:
            step = min(remaining_segment, remaining_pattern)
            next_point = (x + ux * step, y + uy * step)
            if drawing:
                if not current_dash:
                    current_dash.append((x, y))
                current_dash.append(next_point)
            x, y = next_point
            remaining_segment -= step
            remaining_pattern -= step
            if remaining_pattern <= 1e-09:
                if drawing and len(current_dash) >= 2:
                    spawn_polyline_spline(qlabs, current_dash, width, color, z=z)
                    current_dash = []
                drawing = not drawing
                remaining_pattern = dash if drawing else gap
    if drawing and len(current_dash) >= 2:
        spawn_polyline_spline(qlabs, current_dash, width, color, z=z)

def spawn_dashed_arc(qlabs, center, yaw_rad, radius, turn_angle_deg, width, color, z=GUIDE_Z, dash_design_m=DASH_LENGTH_DESIGN_M, gap_design_m=DASH_GAP_DESIGN_M):
    total_length = abs(math.radians(turn_angle_deg) * radius)
    if total_length <= 1e-09 or radius <= 1e-09:
        return
    scale = project_scale()
    dash = max(0.003, float(dash_design_m) * scale)
    gap = max(0.002, float(gap_design_m) * scale)
    cursor = 0.0
    while cursor < total_length - 1e-09:
        end = min(total_length, cursor + dash)
        start_angle = 90.0 - math.degrees(cursor / radius)
        end_angle = 90.0 - math.degrees(end / radius)
        spawn_arc_spline(qlabs, center=center, yaw_rad=yaw_rad, radius=radius, start_angle_deg=start_angle, end_angle_deg=end_angle, width=width, color=color, z=z)
        cursor = end + gap

def curve_center_design_local(radius_design, turn_angle_deg):
    theta = math.radians(turn_angle_deg)
    cx = -0.5 * radius_design * math.sin(theta)
    cy = -0.5 * radius_design * (1.0 + math.cos(theta))
    return (cx, cy)

def spawn_road_surface(qlabs, obj):
    obj_type = str(obj.get('type', ''))
    scale = project_scale()
    width = max(0.001, float(obj.get('width_m', 6.0)) * scale)
    if obj_type == 'continuous_road':
        if bool(obj.get('auto_connector', False)):
            return
        points = scaled_polyline_points(obj, continuous_local_points(obj))
        spawn_polyline_spline(qlabs, points, width, ROAD_COLOR)
        return
    if obj_type in ('curve_45', 'curve_90'):
        turn = 45.0 if obj_type == 'curve_45' else 90.0
        radius_design = float(obj.get('radius_m', 10.0))
        local_center = curve_center_design_local(radius_design, turn)
        center = scaled_world_point(obj, local_center[0], local_center[1])
        spawn_arc_spline(qlabs, center=center, yaw_rad=editor_yaw_to_qlabs_radians(obj.get('rotation_deg', 0.0)), radius=radius_design * scale, start_angle_deg=90.0, end_angle_deg=90.0 - turn, width=width, color=ROAD_COLOR, z=ROAD_Z)
        return

def marking_width_effective(design_width_m):
    return max(0.001, float(design_width_m) * project_scale())

def marking_color(markings, key, default_name):
    name = str(markings.get(f'{key}_color', default_name))
    rgb = MARKING_PRESET_RGB.get(name, MARKING_PRESET_RGB[default_name])
    return [value / 255.0 for value in rgb]

def marking_style(markings, key, default_style):
    style = str(markings.get(f'{key}_style', default_style))
    return 'dashed' if style == 'dashed' else 'solid'

def spawn_marking_polyline(qlabs, obj, local_points, width, color, style):
    points = scaled_polyline_points(obj, local_points)
    if style == 'dashed':
        spawn_dashed_polyline(qlabs, points, width, color, z=MARKING_Z, dash_design_m=CENTER_DASH_LENGTH_DESIGN_M, gap_design_m=CENTER_DASH_GAP_DESIGN_M)
    else:
        spawn_polyline_spline(qlabs, points, width, color, z=MARKING_Z)

def spawn_marking_arc(qlabs, center, yaw, radius, turn, width, color, style):
    if style == 'dashed':
        spawn_dashed_arc(qlabs, center=center, yaw_rad=yaw, radius=radius, turn_angle_deg=turn, width=width, color=color, z=MARKING_Z, dash_design_m=CENTER_DASH_LENGTH_DESIGN_M, gap_design_m=CENTER_DASH_GAP_DESIGN_M)
    else:
        spawn_arc_spline(qlabs, center=center, yaw_rad=yaw, radius=radius, start_angle_deg=90.0, end_angle_deg=90.0 - turn, width=width, color=color, z=MARKING_Z)

def spawn_road_markings(qlabs, obj):
    """Export each road marking with its own visibility/color/style."""
    obj_type = str(obj.get('type', ''))
    if obj_type == 'continuous_road' and bool(obj.get('auto_connector', False)):
        return
    scale = project_scale()
    edge_width = marking_width_effective(EDGE_LINE_WIDTH_DESIGN_M)
    center_width = marking_width_effective(CENTER_LINE_WIDTH_DESIGN_M)
    road_width_design = float(obj.get('width_m', 8.4))
    half_width = road_width_design / 2.0
    edge_offset = max(0.01, half_width - EDGE_INSET_DESIGN_M)
    markings = obj.get('road_markings', {}) or {}
    show_edge_a = bool(markings.get('edge_a', True))
    show_center = bool(markings.get('center', True))
    show_edge_b = bool(markings.get('edge_b', True))
    show_end_bar = bool(markings.get('end_bar', True))
    lane_count = max(1, min(12, int(markings.get('lane_count', 2))))
    lane_divider_offsets = [-half_width + road_width_design * index / float(lane_count) for index in range(1, lane_count)] if show_center and lane_count > 1 else []
    edge_a_color = marking_color(markings, 'edge_a', 'white')
    edge_a_style = marking_style(markings, 'edge_a', 'solid')
    center_color = marking_color(markings, 'center', 'yellow')
    center_style = marking_style(markings, 'center', 'dashed')
    edge_b_color = marking_color(markings, 'edge_b', 'white')
    edge_b_style = marking_style(markings, 'edge_b', 'solid')
    end_color = marking_color(markings, 'end_bar', 'white')
    end_style = marking_style(markings, 'end_bar', 'solid')
    if obj_type == 'continuous_road':
        local_points = continuous_local_points(obj)
        if len(local_points) < 2:
            return
        if show_edge_a:
            spawn_marking_polyline(qlabs, obj, polyline_offset_design(local_points, edge_offset), edge_width, edge_a_color, edge_a_style)
        if show_edge_b:
            spawn_marking_polyline(qlabs, obj, polyline_offset_design(local_points, -edge_offset), edge_width, edge_b_color, edge_b_style)
        for divider_offset in lane_divider_offsets:
            spawn_marking_polyline(qlabs, obj, polyline_offset_design(local_points, divider_offset), center_width, center_color, center_style)
        return
    if obj_type in ('curve_45', 'curve_90'):
        turn = 45.0 if obj_type == 'curve_45' else 90.0
        radius_design = float(obj.get('radius_m', 10.0))
        local_center = curve_center_design_local(radius_design, turn)
        center = scaled_world_point(obj, local_center[0], local_center[1])
        yaw = editor_yaw_to_qlabs_radians(obj.get('rotation_deg', 0.0))
        outer_radius = (radius_design + edge_offset) * scale
        inner_radius = max(0.001, (radius_design - edge_offset) * scale)
        if show_edge_a:
            spawn_marking_arc(qlabs, center, yaw, outer_radius, turn, edge_width, edge_a_color, edge_a_style)
        if show_edge_b:
            spawn_marking_arc(qlabs, center, yaw, inner_radius, turn, edge_width, edge_b_color, edge_b_style)
        for divider_offset in lane_divider_offsets:
            spawn_marking_arc(qlabs, center, yaw, max(0.001, (radius_design + divider_offset) * scale), turn, center_width, center_color, center_style)
        return

def _rotate_vector_world(vx, vy, editor_rotation_deg):
    """Rotate a local world vector by the object's editor rotation."""
    return rotate_local_world(vx, vy, editor_rotation_deg)

def _connection_points_design(obj):
    """Return connectable road endpoints in full-scale design coordinates.

    Each entry contains:
      x, y      world/design position
      tx, ty    unit tangent axis (direction sign is irrelevant)
      width_m   road width
    """
    obj_type = str(obj.get('type', ''))
    width = float(obj.get('width_m', 6.0))
    rotation = float(obj.get('rotation_deg', 0.0))
    local = []
    if obj_type == 'continuous_road':
        if bool(obj.get('auto_connector', False)):
            return []
        points = continuous_local_points(obj)
        if len(points) >= 2:
            start_dx = points[1][0] - points[0][0]
            start_dy = points[1][1] - points[0][1]
            end_dx = points[-1][0] - points[-2][0]
            end_dy = points[-1][1] - points[-2][1]
            local = [(points[0][0], points[0][1], start_dx, start_dy), (points[-1][0], points[-1][1], end_dx, end_dy)]
    elif obj_type in ('curve_45', 'curve_90'):
        turn = 45.0 if obj_type == 'curve_45' else 90.0
        theta = math.radians(turn)
        radius = float(obj.get('radius_m', 10.0))
        dx = radius * math.sin(theta)
        dy = radius * (1.0 - math.cos(theta))
        local = [(-dx / 2.0, +dy / 2.0, 1.0, 0.0), (+dx / 2.0, -dy / 2.0, math.cos(theta), -math.sin(theta))]
    result = []
    for lx, ly, ltx, lty in local:
        x, y = local_to_world_design(obj, lx, ly)
        tx, ty = _rotate_vector_world(ltx, lty, rotation)
        mag = math.hypot(tx, ty)
        if mag <= 1e-09:
            continue
        result.append({'x': x, 'y': y, 'tx': tx / mag, 'ty': ty / mag, 'width_m': width, 'object_id': obj.get('id')})
    return result

def _axis_alignment(a, b):
    """Return absolute tangent-axis alignment in [0,1]."""
    return abs(a['tx'] * b['tx'] + a['ty'] * b['ty'])

def spawn_connection_patches(qlabs, objects):
    """Bridge tiny rendering seams only at actual road connections."""
    endpoints = []
    for obj in objects:
        endpoints.extend(_connection_points_design(obj))
    used_pairs = set()
    for i, a in enumerate(endpoints):
        for j in range(i + 1, len(endpoints)):
            b = endpoints[j]
            if a.get('object_id') == b.get('object_id'):
                continue
            dx = b['x'] - a['x']
            dy = b['y'] - a['y']
            distance = math.hypot(dx, dy)
            if distance > JOIN_MATCH_TOLERANCE_DESIGN_M:
                continue
            if _axis_alignment(a, b) < math.cos(math.radians(12.0)):
                continue
            pair_key = tuple(sorted((i, j)))
            if pair_key in used_pairs:
                continue
            used_pairs.add(pair_key)
            cx_design = (a['x'] + b['x']) / 2.0
            cy_design = (a['y'] + b['y']) / 2.0
            dot = a['tx'] * b['tx'] + a['ty'] * b['ty']
            sign = 1.0 if dot >= 0.0 else -1.0
            tx = a['tx'] + sign * b['tx']
            ty = a['ty'] + sign * b['ty']
            mag = math.hypot(tx, ty)
            if mag <= 1e-09:
                tx, ty = (a['tx'], a['ty'])
            else:
                tx /= mag
                ty /= mag
            half_patch = JOIN_PATCH_LENGTH_DESIGN_M / 2.0
            p1_design = (cx_design - tx * half_patch, cy_design - ty * half_patch)
            p2_design = (cx_design + tx * half_patch, cy_design + ty * half_patch)
            scale = project_scale()
            p1 = (p1_design[0] * scale, p1_design[1] * scale)
            p2 = (p2_design[0] * scale, p2_design[1] * scale)
            patch_width = max(a['width_m'], b['width_m']) * scale
            spawn_straight_spline(qlabs, p1, p2, patch_width, ROAD_COLOR, z=ROAD_Z + 0.0005)

def actor_effective_scale(obj):
    multiplier = max(0.001, float(obj.get('actor_scale', 1.0)))
    if bool(obj.get('scale_with_project', True)):
        multiplier *= project_scale()
    return multiplier

def normalized_rgb(rgb, fallback=(145, 155, 170)):
    if not isinstance(rgb, (list, tuple)) or len(rgb) != 3:
        rgb = fallback
    return [clamp(float(rgb[0]), 0.0, 255.0) / 255.0, clamp(float(rgb[1]), 0.0, 255.0) / 255.0, clamp(float(rgb[2]), 0.0, 255.0) / 255.0]

def _register_actor_handle(obj, actor):
    """Expose an actor by both stable object id and readable identifier."""
    object_id = str(obj.get('id', ''))
    identifier = str(obj.get('identifier', ''))
    if object_id:
        ACTOR_HANDLES[object_id] = actor
    if identifier:
        ACTOR_HANDLES[identifier] = actor

def spawn_basic_shape_part(qlabs, obj, offset, dimensions, color, shape='cube', roughness=0.7, metallic=False):
    """Spawn one part of a composite scenery asset around an object origin."""
    part_scale = actor_effective_scale(obj)
    yaw = editor_yaw_to_qlabs_radians(obj.get('rotation_deg', 0.0))
    local_x = float(offset[0]) * part_scale
    local_y = float(offset[1]) * part_scale
    dx, dy = rotate_local_world(local_x, local_y, obj.get('rotation_deg', 0.0))
    location = [float(obj.get('x', 0.0)) * project_scale() + dx, float(obj.get('y', 0.0)) * project_scale() + dy, TRACK_BASE_Z + float(obj.get('z_m', 0.0)) * project_scale() + float(offset[2]) * part_scale]
    configuration_map = {'cube': QLabsBasicShape.SHAPE_CUBE, 'sphere': QLabsBasicShape.SHAPE_SPHERE, 'cone': QLabsBasicShape.SHAPE_CONE}
    actor = QLabsBasicShape(qlabs)
    actor.spawn(location=location, rotation=[0.0, 0.0, yaw], scale=[max(0.001, float(dimensions[0]) * part_scale), max(0.001, float(dimensions[1]) * part_scale), max(0.001, float(dimensions[2]) * part_scale)], configuration=configuration_map.get(shape, QLabsBasicShape.SHAPE_CUBE), waitForConfirmation=True)
    actor.set_material_properties(color=list(color), roughness=float(roughness), metallic=bool(metallic), waitForConfirmation=True)
    actor.set_enable_dynamics(False, waitForConfirmation=True)
    return actor

def spawn_round_tree(qlabs, obj):
    trunk = spawn_basic_shape_part(qlabs, obj, [0, 0, 1.5], [0.45, 0.45, 3.0], [0.32, 0.16, 0.07])
    spawn_basic_shape_part(qlabs, obj, [0, 0, 3.7], [2.2, 2.2, 2.0], [0.1, 0.42, 0.1], shape='sphere')
    spawn_basic_shape_part(qlabs, obj, [-0.9, 0, 3.5], [1.4, 1.4, 1.4], [0.16, 0.55, 0.14], shape='sphere')
    spawn_basic_shape_part(qlabs, obj, [0.9, 0.15, 3.6], [1.4, 1.4, 1.4], [0.16, 0.55, 0.14], shape='sphere')
    return trunk

def spawn_pine_tree(qlabs, obj):
    trunk = spawn_basic_shape_part(qlabs, obj, [0, 0, 1.25], [0.35, 0.35, 2.5], [0.32, 0.16, 0.07])
    spawn_basic_shape_part(qlabs, obj, [0, 0, 2.7], [2.7, 2.7, 2.4], [0.06, 0.3, 0.08], shape='cone')
    spawn_basic_shape_part(qlabs, obj, [0, 0, 3.7], [2.1, 2.1, 2.2], [0.1, 0.42, 0.1], shape='cone')
    spawn_basic_shape_part(qlabs, obj, [0, 0, 4.6], [1.5, 1.5, 1.9], [0.16, 0.55, 0.14], shape='cone')
    return trunk

def spawn_scene_actor(qlabs, obj):
    global NEXT_SECONDARY_QCAR_ACTOR_NUMBER
    obj_type = str(obj.get('type', ''))
    yaw = editor_yaw_to_qlabs_radians(obj.get('rotation_deg', 0.0))
    actor_scale = actor_effective_scale(obj)
    uniform_scale = [actor_scale, actor_scale, actor_scale]
    configuration = int(obj.get('configuration', 0))
    if obj_type == 'building_box':
        actor = QLabsBasicShape(qlabs)
        dimension_scale = project_scale() if bool(obj.get('scale_with_project', True)) else 1.0
        length = max(0.01, float(obj.get('length_m', 10.0)) * dimension_scale)
        width = max(0.01, float(obj.get('width_m', 8.0)) * dimension_scale)
        height = max(0.01, float(obj.get('height_m', 5.0)) * dimension_scale)
        base_z = TRACK_BASE_Z + float(obj.get('z_m', 0.0)) * project_scale()
        center_location = [float(obj.get('x', 0.0)) * project_scale(), float(obj.get('y', 0.0)) * project_scale(), base_z + height / 2.0]
        actor.spawn(location=center_location, rotation=[0, 0, yaw], scale=[length, width, height], configuration=QLabsBasicShape.SHAPE_CUBE, waitForConfirmation=True)
        actor.set_material_properties(color=normalized_rgb(obj.get('rgb', [145, 155, 170])), roughness=0.65, metallic=False, waitForConfirmation=True)
        return actor
    if obj_type == 'round_tree':
        return spawn_round_tree(qlabs, obj)
    if obj_type == 'pine_tree':
        return spawn_pine_tree(qlabs, obj)
    return None

def spawn_scene_actors(qlabs, objects):
    scene_types = {'building_box', 'pine_tree', 'round_tree'}
    for obj in objects:
        obj_type = obj.get('type')
        if obj_type not in scene_types:
            continue
        if obj_type in {'person', 'animal', 'secondary_qcar2'} and str(obj.get('spawn_mode', 'immediate')) == 'triggered':
            continue
        actor = spawn_scene_actor(qlabs, obj)
        object_id = str(obj.get('id', ''))
        if actor is not None and object_id:
            _register_actor_handle(obj, actor)

def spawn_qcar2(qlabs):
    starts = [obj for obj in TRACK_DATA.get('objects', []) if obj.get('type') == 'qcar2_start']
    if not starts:
        print('No QCar2 Start marker in track; roads only.')
        return None
    obj = starts[0]
    scale = project_scale()
    qcar = QLabsQCar2(qlabs)
    qcar.spawn_id(actorNumber=0, location=[float(obj.get('x', 0.0)) * scale, float(obj.get('y', 0.0)) * scale, TRACK_BASE_Z + 2.0 * scale], rotation=[0, 0, editor_yaw_to_qlabs_radians(obj.get('rotation_deg', 0.0))], scale=[scale, scale, scale], configuration=0, waitForConfirmation=True)
    _register_actor_handle(obj, qcar)
    return qcar

def main():
    print('Connecting to QLabs...')
    qlabs = QuanserInteractiveLabs()
    if not qlabs.open('localhost'):
        print('Unable to connect to QLabs.')
        print('Open QLabs in the Plane workspace and try again.')
        sys.exit(1)
    print('Connected to QLabs.')
    qlabs.destroy_all_spawned_actors()
    QLabsRealTime().terminate_all_real_time_models()
    time.sleep(0.5)
    apply_environment_settings(qlabs)
    objects = TRACK_DATA.get('objects', [])
    for obj in objects:
        spawn_road_surface(qlabs, obj)
    spawn_connection_patches(qlabs, objects)
    for obj in objects:
        spawn_road_markings(qlabs, obj)
    spawn_scene_actors(qlabs, objects)
    qcar = spawn_qcar2(qlabs)
    if qcar is not None:
        QLabsRealTime().start_real_time_model(rtmodels.QCAR2)
        time.sleep(0.5)
        starts = [obj for obj in objects if obj.get('type') == 'qcar2_start']
        camera_view = str(starts[0].get('camera_view', 'third_person')) if starts else 'third_person'
        if camera_view == 'first_person':
            qcar.possess(QLabsQCar2.CAMERA_CSI_FRONT)
        else:
            qcar.possess(QLabsQCar2.CAMERA_TRAILING)
    print('QLabs track created. Project scale = ' + str(TRACK_DATA.get('project', {}).get('scale_name', '1:1')))
if __name__ == '__main__':
    main()
